#!/usr/bin/env python3
"""Project-local workbench entry; generated by workspace_deploy.py."""
import json
from pathlib import Path
import re
import subprocess
import sys

root = Path(__file__).resolve().parent
try:
    state = json.loads((root / ".workbench/deployment.json").read_text(encoding="utf-8"))
    revision = state["active_revision"]
    if not re.fullmatch(r"[0-9a-f]{40}", revision):
        raise ValueError("invalid active revision")
    core = root / ".workbench/core" / revision
    if core.resolve() != core or not (core / ".git").is_dir():
        raise ValueError("invalid core checkout")
    args = sys.argv[1:]
    if not args or args[0] in ("init", "update", "status", "rollback", "deps"):
        args = args or ["status"]
        command = [sys.executable, "-B", str(core / "scripts/workspace_deploy.py"), args[0], str(root), *args[1:]]
    else:
        command = [sys.executable, "-B", str(core / "scripts/project_workspace.py"),
                   "--config", str(root / "管线设置/config.local.json"), *args]
    raise SystemExit(subprocess.call(command, cwd=root))
except (OSError, ValueError, KeyError) as error:
    print(str(error), file=sys.stderr)
    raise SystemExit(1)
